import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
const jobs = new Map(); let next = 0;
const timers = { schedule(fn, ms) { assert.equal(ms, 120); const id = ++next; jobs.set(id, fn); return id; }, cancel(id) { jobs.delete(id); } };
const run = () => { const entries = [...jobs]; jobs.clear(); for (const [, fn] of entries) fn(); };
const store = createDraftStore(); const archive = createReceiptArchive(); const statuses = [];
const w = createWorkspace({store, archive, timers, renderDocument() {}, renderStatus(x) { statuses.push(x); }});
w.open('a'); w.edit('1'); w.edit('12'); assert.equal(store.read('a'), ''); assert.equal(jobs.size, 1); run(); assert.equal(store.read('a'), '12'); assert.equal(statuses.length, 1);
w.edit('123'); run(); assert.equal(store.read('a'), '123');
w.edit('final'); w.close(); assert.equal(store.read('a'), 'final'); assert.equal(jobs.size, 0); assert.equal(statuses.length, 2);
w.open('a'); w.edit('submit'); const receipt = w.submit(); assert.deepEqual(receipt, {id:'a', text:'submit'}); assert.equal(store.read('a'), 'submit'); assert.equal(jobs.size, 0);
w.edit('later'); w.open('b'); assert.equal(store.read('a'), 'later'); assert.equal(archive.list()[0].text, 'submit');
console.log('basic checks passed');
EOF"

